// Customer and supplier operations use server records; no financial state is stored in the browser.
export function createWorkflows({api,esc,btn,money,date,openModal,closeModal,status,issuer,client,refresh,download,csrf}){
 const h=esc,fmt=n=>money(Number(n||0)/100),when=s=>s?date(s.replace(/Z$/,'')+'Z'):'—';
 const names={requested:'Заявка на оплату',prepared:'Проверена, готова к оплате',sent:'Перевод отправлен',bank_credited:'Зачисление подтверждено банком',received:'Получение подтверждено',cancelled:'Реестр отменён',returned:'Перевод возвращён',confirmed:'Подтверждено',pending:'В обработке',unknown:'Требуется сверка',paid:'Возвращено',partially_paid:'Частичный возврат',review:'На рассмотрении',awaiting_issuer:'Запрошен ответ поставщика',approved:'Согласовано',rejected:'Отказ с обоснованием',open:'Открыто',waiting:'Ожидает ответа',answered:'Получен ответ',closed:'Закрыто',completed:'Завершено'};
 const label=s=>names[s]||s||'—';
 const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(s=>`<th>${h(s)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${heads.length}">Записей пока нет.</td></tr>`}</tbody></table></div>`;
 const row=cells=>'<tr>'+cells.map(c=>'<td>'+c+'</td>').join('')+'</tr>';
 const files=items=>(items||[]).map(f=>`<p><a class="text-link" href="/api/gift/files/download/?id=${encodeURIComponent(f.id)}">${h(f.original_name)}</a><small> ${when(f.created_at)}</small></p>`).join('');
 const upload=(kind,id,title='Приложить документ')=>`<form data-work-form="file" data-kind="${kind}" data-id="${h(id)}" class="fields"><label>${title}<input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.docx" required></label><p class="note">PDF, PNG, JPG или DOCX до 10 МБ. Документ доступен участникам обращения или расчёта и сотрудникам Pina.</p><button class="btn outline small">Загрузить документ</button><p class="form-error" role="alert" hidden></p></form>`;
 let eligible=[],selected=[],registryFilters=new URLSearchParams();
 async function profile(){const p=await api('profile/');return `<section class="panel"><h2>Контактные данные</h2><p>Email: <b>${h(p.email)}</b> · ID ${p.id}</p><form data-work-form="profile" class="fields"><label>ФИО<input name="name" maxlength="180" value="${h(p.contact?.full_name||'')}"></label><label>Телефон<input name="phone" type="tel" maxlength="60" value="${h(p.contact?.phone||'')}"></label><p class="note">Email служит для входа. Для его изменения обратитесь в поддержку: потребуется подтверждение обоих адресов.</p><button class="btn">Сохранить</button><p class="form-error" role="alert" hidden></p></form></section>`;}
 async function cases(merchant=false){const data=await api('cases/'+(merchant?'?issuerId='+encodeURIComponent(issuer()):''));return `<section class="panel"><h2>${merchant?'Запросы и документы':'Поддержка'}</h2><p>По возврату откройте нужную карту. По остальным вопросам создайте обращение; ответы и документы сохранятся здесь.</p>${btn('Создать обращение','work-case-new','outline',merchant?'merchant':'client')}</section>${data.items.map(c=>`<section class="panel"><h3>${h(c.topic)}</h3><p>${h(c.body)}</p><p><span class="badge">${h(label(c.status))}</span> · До ${when(c.due_at)}</p><p class="note">Основание: ${h(c.object_ref||'Общий вопрос')}</p>${c.messages.map(m=>`<article class="claim"><small>${m.is_staff?'Команда Pina Market':h(m.email)} · ${when(m.created_at)}</small><p>${h(m.body)}</p></article>`).join('')}${files(c.files)}${c.status!=='closed'?`<form data-work-form="reply" data-id="${h(c.id)}" class="fields"><label>Ответ<textarea name="body" required maxlength="5000"></textarea></label><button class="btn outline small">Отправить ответ</button><p class="form-error" hidden role="alert"></p></form>${upload('case',c.id)}`:''}</section>`).join('')}`;}
 async function card(id){const d=await api('cards/detail/?id='+encodeURIComponent(id)),c=d.card,a=d.activation;return `<h2>Карта ${h(id.slice(0,8))}</h2><dl class="receipt"><dt>Номинал</dt><dd>${fmt(c.nominal_minor)}</dd><dt>Место исполнения</dt><dd>Кыргызская Республика, ${h(d.fulfillment?.fulfillment_address||'по условиям вашего заказа')}</dd><dt>Территория</dt><dd>Получение товара и оказание услуги в РФ по этой карте не предусмотрены.</dd><dt>Выпуск</dt><dd>${h(({not_issued:'Код ещё не создан',issued:'Код создан',cancelled:'Аннулирована'})[c.issuance_status]||label(c.issuance_status))}</dd><dt>Приём поставщиком</dt><dd>${a?`${h(label(a.status))} · ${when(a.activated_at)}<br>${h(a.actor_email)}<br>Покупатель: ${h(a.buyer_name)}<br>Договор / заказ: ${h(a.contract_reference)}`:'Карта ещё не принята'}</dd>${c.expires_at?`<dt>Действительна до</dt><dd>${when(c.expires_at)}</dd>`:''}</dl>${c.payment_status==='confirmed'&&c.refund_status==='none'?btn('Обратиться за возвратом','live-refund','outline full',id):''}${d.refunds.map(r=>`<article class="claim"><h3>Возврат ${h(r.id.slice(0,8))}</h3><span class="badge">${h(label(r.status))}</span><p>${h(r.reason)}</p><p>${h(r.resolution||'Обращение принято. Решение появится здесь.')}</p><p class="note">Срок: ${when(r.due_at)}${r.paid_at?' · Возвращено '+fmt(r.amount_minor)+' · '+when(r.paid_at):''}</p>${files(r.files)}${!['paid','rejected'].includes(r.status)?upload('refund',r.id,'Документ к обращению'):''}</article>`).join('')}`;}
 async function registry(){const query=location.hash.split('?')[1]||'';registryFilters=new URLSearchParams(query);const q=new URLSearchParams(registryFilters);q.set('issuerId',issuer());const d=await api('merchant/registry/?'+q);return `<form data-work-form="registry-filter" class="panel admin-filters"><label>Поиск по покупателю, договору, карте<input name="search" value="${h(registryFilters.get('search')||'')}" maxlength="200"></label><label>С даты<input type="date" name="from" value="${h(registryFilters.get('from')||'')}"></label><label>По дату<input type="date" name="to" value="${h(registryFilters.get('to')||'')}"></label><button class="btn small">Найти</button><a href="#/merchant/registry">Сбросить</a></form><section class="panel merchant-registry">${table(['Карта / дата','Покупатель / договор','Номинал','Статус / расчёт','Кто принял'],d.items.map(r=>row([h(r.card_id.slice(0,8))+'<small>'+when(r.activated_at||r.created_at)+'</small>',h(r.buyer_name)+'<small>'+h(r.contract_reference)+'</small>',fmt(r.nominal_minor),h(label(r.status))+(r.refund_status!=='none'?'<small>Есть обращение на возврат</small>':'')+(r.settlement_id?'<small>Реестр '+h(r.settlement_id.slice(0,8))+'</small>':''),h(r.actor_email||'—')])))}<div class="admin-pagination"><span>Найдено ${d.total}. Страница ${d.page} из ${d.pages}</span>${d.page>1?btn('Назад','work-registry-page','outline small',d.page-1):''}${d.page<d.pages?btn('Далее','work-registry-page','outline small',d.page+1):''}</div></section>${btn('Скачать реестр CSV','work-registry-export','outline')}`;}
 async function settlements(balanceView){const d=await api('merchant/balance/?issuerId='+encodeURIComponent(issuer())),t=d.totals||{};return `<div class="merchant-stat-grid">${[['Доступно к заявке',t.available_minor],['В реестрах к оплате',t.reserved_minor],['Перечислено по номиналу',t.settled_minor],['На рассмотрении возвратов',t.refund_hold_minor]].map(([n,v])=>`<article class="summary-stat"><span>${n}</span><strong>${fmt(v)}</strong></article>`).join('')}</div><section class="panel"><h2>Заказать оплату</h2><p>Выберите принятые карты и направьте реестр Pina Market. Оператор проверит сумму и выполнит банковский перевод с учётом согласованных удержаний.</p>${Number(t.available_minor)>0?btn('Заказать оплату','work-payout',''):'<p>Нет свободных активаций для новой заявки.</p>'}<p class="note">Суммы выше — учёт взаиморасчётов по номиналу. После регистрации отправленного перевода номинал, включающий сумму поставщику и удержания, списывается из обязательств к оплате. Фактическое зачисление подтверждается отдельно. Заявка не меняет сроков расчёта по договору.</p></section><details class="panel"><summary>Фактический баланс технологической платформы</summary>${balanceView(d.provider)}<p class="note">Остаток платформы сверяется вручную и не заменяет банковский расчёт.</p></details><section class="panel"><h2>Заявки и расчёты</h2>${table(['Реестр / дата','Номинал','К перечислению','Состояние',''],d.settlements.map(s=>row([h(s.id.slice(0,8))+'<small>'+when(s.created_at)+'</small>',fmt(s.gross_minor),fmt(s.expected_net_minor??s.net_minor),h(label(s.status)),btn('Реестр и документы','work-settlement','outline small',s.id)])))}</section>`;}
 async function settlement(id){const d=await api('merchant/settlement/?id='+encodeURIComponent(id)),s=d.settlement;openModal(`<h2>Расчёт ${h(id.slice(0,8))}</h2><dl class="receipt">${[['Номинал карт',fmt(s.gross_minor)],['Вознаграждение Pina 0,1%',fmt(s.agent_fee_minor)],['Валютный контроль 0,2%',fmt(s.control_fee_minor)],['Перевод 0,6%',fmt(s.transfer_fee_minor)],['К перечислению',fmt(s.expected_net_minor)],['Состояние',label(s.status)]].map(([k,v])=>'<dt>'+k+'</dt><dd>'+h(v)+'</dd>').join('')}</dl><a class="btn outline small" href="/api/gift/merchant/statement/?id=${encodeURIComponent(id)}">Скачать реестр и расчёт</a>${table(['Карта','Покупатель','Договор','Номинал'],d.items.map(a=>row([h(a.card_id.slice(0,8)),h(a.buyer_name),h(a.contract_reference),fmt(a.nominal_minor)])))}<h3>Документы расчёта</h3>${files(d.files)||'<p>Подтверждающих документов пока нет.</p>'}${s.status==='bank_credited'?btn('Подтвердить получение перевода','live-settlement-ack','full',id):''}${upload('settlement',id,'Подтверждение поступления или закрывающий документ')}<h3>История</h3>${d.events.map(e=>'<article class="claim"><small>'+when(e.created_at)+' · '+h(label(e.kind))+'</small><p>'+h(e.body)+'</p><p>'+h(e.reference)+'</p></article>').join('')}`,'Реестр и документы');}
 async function click(action,id){
  if(action==='work-registry-page'){registryFilters.set('page',id);location.hash='/merchant/registry?'+registryFilters;return;}
  if(action==='work-registry-export'){let all=[];for(let page=1;page<=100;page++){const q=new URLSearchParams(registryFilters);q.set('issuerId',issuer());q.set('page',page);const d=await api('merchant/registry/?'+q);if(d.total>10000)throw Error('Сузьте период: в выгрузке больше 10 000 строк');all.push(...d.items);if(page>=d.pages)break;}const quote=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';download(new Blob(['\ufeff'+[['Карта','Покупатель','Договор','Номинал RUB','Статус','Дата UTC','Сотрудник','Реестр'],...all.map(r=>[r.card_id,r.buyer_name,r.contract_reference,Number(r.nominal_minor)/100,r.status,r.activated_at,r.actor_email,r.settlement_id])].map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'Pina-registry.csv');return;}
  if(action==='work-settlement')return settlement(id);
  if(action==='work-payout'){const d=await api('merchant/registry/?issuerId='+encodeURIComponent(issuer())+'&eligible=1&limit=100');eligible=d.items;if(!eligible.length)throw Error('Нет доступных активаций');openModal(`<h2>Заявка на оплату</h2><p>Выберите до 100 активаций одного поставщика.</p><form data-work-form="payout" class="fields">${table(['Включить','Покупатель / договор','Номинал'],eligible.map(a=>row([`<input type="checkbox" name="activation" value="${h(a.id)}" checked aria-label="Включить ${h(a.contract_reference)}">`,h(a.buyer_name)+'<small>'+h(a.contract_reference)+'</small>',fmt(a.nominal_minor)])))}<label>Комментарий или номер счёта<textarea name="note" required maxlength="3000"></textarea></label><label class="checkline"><input type="checkbox" required><span>Проверил ФИО, договоры, номиналы и реквизиты компании. Удержания: агент 0,1%, банк 0,8%.</span></label><button class="btn full">Направить заявку Pina Market</button><p class="form-error" role="alert" hidden></p></form>`,'Заказать оплату');return;}
  if(action==='work-case-new'){openModal(`<h2>Новое обращение</h2><form data-work-form="case" data-merchant="${id==='merchant'?'1':'0'}" class="fields"><label>Тема<input name="topic" required maxlength="200"></label><label>Заказ, карта или реестр — если есть<input name="objectRef" maxlength="100"></label><label>Сообщение<textarea name="body" required maxlength="5000"></textarea></label><button class="btn full">Отправить обращение</button><p class="form-error" role="alert" hidden></p></form>`,'Обращение');return;}
 }
 async function submit(f,d){const kind=f.dataset.workForm;
  if(kind==='registry-filter'){const q=new URLSearchParams();for(const [k,v] of Object.entries(d))if(v)q.set(k,v);location.hash='/merchant/registry'+(q.size?'?'+q:'');return;}
  if(kind==='profile'){await api('profile/',d);status('Контактные данные сохранены.');return;}
  if(kind==='reply'){await api('cases/reply/',{id:f.dataset.id,body:d.body});status('Ответ отправлен.');await refresh();return;}
  if(kind==='case'){await api('cases/',{...d,issuerId:f.dataset.merchant==='1'?issuer():''});closeModal();status('Обращение зарегистрировано.');location.hash=f.dataset.merchant==='1'?'/merchant/requests':'/account/support';await refresh();return;}
  if(kind==='payout'){const ids=[...f.querySelectorAll('[name=activation]:checked')].map(x=>x.value);if(!ids.length)throw Error('Выберите хотя бы одну активацию');const key=f.dataset.key||(f.dataset.key=crypto.randomUUID());await api('merchant/settlements/request/',{issuerId:issuer(),activationIds:ids,note:d.note,key});closeModal();status('Заявка направлена. Выбранные карты включены в реестр.');await refresh();return;}
  if(kind==='file'){const file=f.querySelector('[name=file]').files[0];if(!file||file.size>10*1024*1024)throw Error('Загрузите документ до 10 МБ');const body=new FormData();body.set('kind',f.dataset.kind);body.set('objectId',f.dataset.id);body.set('file',file);const r=await fetch('/api/gift/files/upload/',{method:'POST',credentials:'same-origin',headers:{'X-CSRFToken':csrf()},body}),v=await r.json();if(!r.ok)throw Error(v.error||'Загрузка не выполнена');status('Документ сохранён.');if(f.dataset.kind==='settlement')return settlement(f.dataset.id);if(f.dataset.kind==='refund'){openModal(await card((await api('state/')).refunds.find(x=>x.id===f.dataset.id).card_id),'Карта и возврат');return;}await refresh();}
 }
 return {profile,cases,card,registry,settlements,click,submit};
}
